// The *clearnight, *mostlyclearnight and *partlycloudynight icons are WabbitWeather
// additions: the converted set has no moon, so the sun was swapped for a crescent
// in the same line style, drawn in the cloud white.
//
// Format (MiniGrafx paletted bitmap):
//   byte 0      version (1)
//   byte 1      bit depth (2)
//   bytes 2-3   width,  16-bit big-endian
//   bytes 4-5   height, 16-bit big-endian
//   then 2 bits per pixel, MSB first, indexing a 4-colour palette.
//   Row stride is (width * 2 + 7) / 8 bytes. The original file's "round width
//   to next byte" comments are misleading: its arrays were just over-allocated,
//   and have been trimmed to size here.
//
// Palette indices: 0 background, 1 clouds and moon, 2 sun, 3 rain/snow/edges.
// The colours themselves live in meteoconPalette[] in All_Settings.h.

#pragma once

#include <TFT_eSPI.h>

/***************************************************************************************
**   Draw a Meteocon centred in a boxW x boxH slot at x, y. Any part of the slot the
**   icon doesn't cover is filled with palette[0] so the previous icon can't show.
**   An icon larger than the slot (a few minis are 50x51) is cropped evenly to fit.
***************************************************************************************/
static void drawMeteocon(TFT_eSPI &tft, const uint8_t *icon, int32_t x, int32_t y,
                         int32_t boxW, int32_t boxH, const uint16_t *palette) {
  int32_t w = (pgm_read_byte(icon + 2) << 8) | pgm_read_byte(icon + 3);
  int32_t h = (pgm_read_byte(icon + 4) << 8) | pgm_read_byte(icon + 5);
  int32_t stride = (w * 2 + 7) / 8;
  const uint8_t *data = icon + 6;

  // Source window into the icon, cropped to the slot if needed
  int32_t srcX = w > boxW ? (w - boxW) / 2 : 0;
  int32_t srcY = h > boxH ? (h - boxH) / 2 : 0;
  int32_t drawW = w > boxW ? boxW : w;
  int32_t drawH = h > boxH ? boxH : h;

  int32_t ox = x + (boxW - drawW) / 2;
  int32_t oy = y + (boxH - drawH) / 2;

  // Blank the slot margins around the icon
  tft.fillRect(x, y, boxW, oy - y, palette[0]);
  tft.fillRect(x, oy + drawH, boxW, y + boxH - (oy + drawH), palette[0]);
  tft.fillRect(x, oy, ox - x, drawH, palette[0]);
  tft.fillRect(ox + drawW, oy, x + boxW - (ox + drawW), drawH, palette[0]);

  // Stream the pixels as runs of the same palette index
  tft.startWrite();
  tft.setAddrWindow(ox, oy, drawW, drawH);
  for (int32_t row = srcY; row < srcY + drawH; row++) {
    const uint8_t *line = data + row * stride;
    uint8_t runIdx = 0;
    uint32_t runLen = 0;
    for (int32_t col = srcX; col < srcX + drawW; col++) {
      uint8_t idx = (pgm_read_byte(line + (col >> 2)) >> (6 - 2 * (col & 3))) & 0x03;
      if (runLen && idx != runIdx) {
        tft.pushBlock(palette[runIdx], runLen);
        runLen = 0;
      }
      runIdx = idx;
      runLen++;
    }
    tft.pushBlock(palette[runIdx], runLen);
  }
  tft.endWrite();
}

